 for(const [english,russian] of Object.entries(boundedRu)){en[english]=english;en[russian]??=english;}
 let language='ru';try{if(localStorage.getItem('agentcity-language')==='en')language='en';}catch{}
 const originals=[];
 function t(message,values={}){
  if(typeof message!=='string')return message;
  let translated=language==='en'?(en[message]??message):(boundedRu[message]??message);
  if(language==='en'&&translated===message){
   if(message.startsWith('Не проверена: '))return 'Not checked: '+t(message.slice(14));
   if(message.includes(' · Не удалось сохранить проверку'))return t(message.replace(' · Не удалось сохранить проверку',''))+' · '+t('Не удалось сохранить проверку');
   const http=message.match(/^Источник вернул HTTP (\d+)\. Попробуй обновить позже\.$/);
   if(http)translated=`The source returned HTTP ${http[1]}. Try refreshing later.`;
   else if(/ · HTTP /i.test(message)){const [label,code]=message.split(/ · HTTP /i);translated=t(label)+' · HTTP '+code;}
   else {const label=Object.keys(en).find(key=>key.toLowerCase()===message.toLowerCase());if(label)translated=en[label];}
  }
  return translated.replace(/\{(\w+)\}/g,(whole,key)=>Object.hasOwn(values,key)?String(values[key]):whole);
 }
 function init(){
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
   const node=walker.currentNode,source=node.nodeValue;
   if(en[source.trim()]&&!['SCRIPT','STYLE'].includes(node.parentElement.tagName))originals.push(()=>{node.nodeValue=source.replace(source.trim(),t(source.trim()));});
  }
  for(const node of document.querySelectorAll('[aria-label],[placeholder],[title]'))for(const attr of ['aria-label','placeholder','title']){
   const source=node.getAttribute(attr);if(source&&en[source])originals.push(()=>node.setAttribute(attr,t(source)));
  }
  apply();
 }
 function apply(){document.documentElement.lang=language;document.title=/^agent-city-[a-f0-9]{32}\.localhost$/.test(location.hostname)?'Agent City ['+location.hostname+']':(language==='en'?'Agent City — models':'Agent City — модели');for(const render of originals)render();if(typeof document.dispatchEvent==='function'&&typeof CustomEvent==='function')document.dispatchEvent(new CustomEvent('agentcity-language-change'));}
 function setLanguage(value){language=value==='en'?'en':'ru';try{localStorage.setItem('agentcity-language',language);}catch{}apply();}
 return {t,init,setLanguage,get language(){return language;},get locale(){return language==='en'?'en-US':'ru-RU';}};
